MIDDLEWARE = [
	"utils.tenant_db_router.TenantSubdomainMiddleware",
	"django.middleware.security.SecurityMiddleware",
	...
]
TENANT_MAP = {"localhost":"default", "tenant_1":"default"}
DATABASE_ROUTERS = ["utils.tenant_db_router.TenantDatabaseRouter"]

